package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.DateTimeZoneMidday;
import org.joda.time.Instant;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.DateTimeParser;
import org.joda.time.format.DateTimeParserBucket;
import org.joda.time.年月;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class DateTimeFormatter_parseInto_TriageGen2Test {

    private DateTimeFormatter formatter;
    private ReadWritableInstant mockInstant;
    private DateTimeParser mockParser;

    @Before
    public void setUp() {
        // We use a real DateTimeFormat to get a valid parser/printer structure 
        // because the method relies on internal state like iLocale, iPivotYear, etc.
        formatter = DateTimeFormat.forPattern("yyyy-MM-dd").getParser();
        mockInstant = mock(ReadWritableInstant.class);
        mockParser = mock(DateTimeParser.class);
    }

    /**
     * Tests the exception when instant is null.
     */
    @Test
    public void testParseInto_NullInstant_ThrowsException() {
        assertThrows(IllegalArgumentException.class, () -> {
            formatter.parseInto(null, "2023-01-01", 0);
        });
    }

    /**
     * Tests a successful parse where no offset is parsed and no specific zone is set in formatter.
     */
    @Test
    public void testParseInto_Success_Basic() {
        // Setup mock instant behavior
        long millis = 1672531200000L; // 2023-01-01
        when(mockInstant.getMillis()).thenReturn(millis);
        when(mockInstant.getChronology()).thenReturn(org.joda.time.ISOChronology.getDateTimeZone().getChronology());

        // We need a real parser or a very well-behaved mock to avoid NPE in bucket/parser logic
        // Using a real formatter for the core logic to ensure internal fields like iLocale are initialized
        DateTimeFormatter realFormatter = DateTimeFormat.forPattern("yyyy-MM-dd").getParser();

        // Mocking the parser behavior inside the bucket logic is hard via mock(DateTimeParser) 
        // because the method calls parser.parseInto(bucket, text, position)
        // Instead, we use a real formatter but control the text
        String text = "2023-01-01";
        int position = 0;

        int result = realFormatter.parseInto(mockInstant, text, position);

        assertEquals(0, result); 
        // Verify that setMillis was called (meaning parsing happened)
        verify(mockInstant, atLeastOnce()).setMillis(anyLong());
        verify(mockInstant, atLeastOnce()).setChronology(any(Chronology.class));
    }

    /**
     * Tests the branch where iOffsetParsed is true and an offset is found in the bucket.
     */
    @Test
    public void testParseInto_WithOffsetParsed() {
        // Create a formatter that expects an offset
        DateTimeFormatter offsetFormatter = DateTimeFormat.forPattern("yyyy-MM-dd Z").withOffsetParsed().getParser();

        long millis = 1672531200000L;
        when(mockInstant.getMillis()).thenReturn(millis);
        when(mockInstant.getChronology()).thenReturn(org.joda.time.ISOChronology.getInstanceUTC());

        String text = "2023-01-01 +05:00";
        int position = 0;

        int result = offsetFormatter.parseInto(mockInstant, text, position);

        // Assertions to ensure the flow passed through the offset parsing branch
        verify(mockInstant, atLeastOnce()).setMillis(anyLong());
        verify(mockInstant, atLeastOnce()).setChronology(any(Chronology.class));
    }

    /**
     * Tests the branch where iZone is explicitly set in the formatter.
     */
    @Test
    public void testParseInto_WithExplicitZone() {
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter zoneFormatter = DateTimeFormat.forPattern("yyyy-MM-dd").withZone(zone).getParser();

        long millis = 1672531200000L;
        when(mockInstant.getMillis()).thenReturn(millis);
        when(mockInstant.getChronology()).thenReturn(org.joda.time.ISOChronology.getInstanceUTC());

        String text = "2023-01-01";
        int position = 0;

        zoneFormatter.parseInto(mockInstant, text, position);

        // Verify that the explicit zone was applied to the instant
        verify(mockInstant, atLeastOnce()).setZone(zone);
    }

    /**
     * Tests the branch where bucket.getZone() is not null but iOffsetParsed is false.
     */
    @Test
    public void testParseInto_WithBucketZone() {
        // Pattern that includes zone info but we don't call withOffsetParsed()
        // This triggers the 'else if (bucket.getZone() != null)' branch
        DateTimeFormatter bucketZoneFormatter = DateTimeFormat.forPattern("yyyy-MM-dd VV").getParser();

        long millis = 1672531200000L;
        when(mockInstant.getMillis()).thenReturn(millis);
        when(mockInstant.getChronology()).thenReturn(org.joda.time.ISOChronology.getInstanceUTC());

        String text = "2023-01-01 UTC";
        int position = 0;

        bucketZoneFormatter.parseInto(mockInstant, text, position);

        verify(mockInstant, atLeastOnce()).setChronology(any(Chronology.class));
    }

    /**
     * Tests the pivot year and default year logic by using a custom formatter.
     */
    @Test
    public void testParseInto_WithPivotAndDefaultYear() {
        DateTimeFormatter customFormatter = DateTimeFormat.forPattern("yy-MM-dd")
                .withPivotYear(2000)
                .withDefaultYear(2023)
                .getParser();

        long millis = 1672531200000L;
        when(mockInstant.getMillis()).thenReturn(millis);
        when(mockInstant.getChronology()).thenReturn(org.joda.time.ISOChronology.getInstanceUTC());

        String text = "23-01-01";
        int position = 0;

        // This tests the defaultYear calculation and the bucket initialization
        int result = customFormatter.parseInto(mockInstant, text, position);

        // If it doesn't throw exception, the logic for defaultYear/pivotYear is covered
        verify(mockInstant, atLeastOnce()).setMillis(anyLong());
    }

    /**
     * Tests with different Locale to cover iLocale branch.
     */
    @Test
    public void testParseInto_WithLocale() {
        DateTimeFormatter localeFormatter = DateTimeFormat.forPattern("MMMM dd, yyyy")
                .withLocale(Locale.FRENCH)
                .getParser();

        long millis = 1672531200000L;
        when(mockInstant.getMillis()).thenReturn(millis);
        when(mockInstant.getChronology()).thenReturn(org.joda.time.ISOChronology.getInstanceUTC());

        // "janvier" is January in French
        String text = "janvier 01, 2023";
        int position = 0;

        int result = localeFormatter.parseInto(mockInstant, text, position);

        // Verify parsing succeeded
        verify(mockInstant, atLeastOnce()).setMillis(anyLong());
    }
}
